using System;using System.Collections.Generic;using System.Linq;
namespace IdleRestaurant{
 [Serializable,UnityEngine.Scripting.Preserve] public sealed class CleanupMess{public int id,kind,table=-1,count=1,sourceSeat=-1;public float x,z;public double created;}
 [Serializable,UnityEngine.Scripting.Preserve] public sealed class CleanupPoint{public float x,z;public CleanupPoint(float x,float z){this.x=x;this.z=z;}}
 [Serializable,UnityEngine.Scripting.Preserve] public sealed class CleanupVisit{public int id,outlet,index,target=-1,waypoint,phase;public bool active,paid;public float x=4.68f,z=-6.1f,yaw;public double clock,reward;public int[] messIds=Array.Empty<int>();public List<CleanupPoint> path=new List<CleanupPoint>();}
 public sealed partial class RestaurantGame{
  public Action<int,double> CleanupPaid;
  public void EnsureCleanupState(){if(State.cleanupJob==null)State.cleanupJob=new CleanupVisit();foreach(var o in State.outlets)if(o.dirt==null)o.dirt=new List<CleanupMess>();}
  public int MessCount(int outlet)=>State.outlets[outlet].dirt?.Count??0;
  public double CleanupWait=>Math.Max(0,State.cleanupReadyUtc-Now());
  public void LeaveDirtyPlate(int outlet,ServiceGuest guest){if(guest.plateLeftOnTable||guest.seat<0)return;guest.plateLeftOnTable=true;if(guest.returnedPlate)return;var list=State.outlets[outlet].dirt;int table=guest.seat/2;var old=list.FirstOrDefault(m=>m.kind==0&&m.table==table);if(old!=null){old.count=Math.Min(3,old.count+1);return;}list.Add(new CleanupMess{id=++State.cleanupSequence,kind=0,table=table,sourceSeat=guest.seat,x=-2.15f+(table%2)*4.3f,z=-2.5f+(table/2)*2+.32f,created=State.seconds});}
  public bool RequestCleanup(int outlet){EnsureCleanupState();if(!Family||!State.introComplete||outlet<0||outlet>=State.outlets.Length||!State.outlets[outlet].open)return false;if(MessCount(outlet)==0){Feedback?.Invoke("Everything here is tidy");return false;}if(State.cleanupJob.active){Feedback?.Invoke("Your janitor is cleaning this visit's messes");return false;}State.cleanupGuideSeen=true;if(CleanupWait>0){State.queuedCleanup=outlet;Feedback?.Invoke("Janitor returns in "+Math.Ceiling(CleanupWait)+"s. Cleanup queued.");return true;}StartCleanup(outlet);return true;}
  void StartCleanup(int outlet){State.queuedCleanup=-1;var job=new CleanupVisit{id=++State.cleanupVisitSequence,outlet=outlet,active=true,reward=Math.Max(0,NetworkIncome()*Balance.cleanupRewardMinutes),messIds=State.outlets[outlet].dirt.OrderBy(m=>m.z).ThenBy(m=>m.x).Select(m=>m.id).ToArray()};State.cleanupJob=job;SetCleanupTarget(job);Feedback?.Invoke("Janitor on the way · all current messes");}
  void CleanupPath(CleanupVisit job,params CleanupPoint[] points){job.path=new List<CleanupPoint>(points);job.waypoint=0;job.clock=0;}
  void SetCleanupTarget(CleanupVisit job){var list=State.outlets[job.outlet].dirt;while(job.index<job.messIds.Length&&!list.Any(m=>m.id==job.messIds[job.index]))job.index++;if(job.index>=job.messIds.Length){job.phase=2;job.target=-1;CleanupPath(job,new CleanupPoint(4.05f,job.z),new CleanupPoint(4.05f,-4.05f),new CleanupPoint(4.68f,-5.2f),new CleanupPoint(4.68f,-6.1f));return;}var mess=list.First(m=>m.id==job.messIds[job.index]);job.target=mess.id;float targetX=mess.x,targetZ=mess.kind==0?-2.5f+(mess.table/2)*2+.8f:mess.z+.45f;job.phase=0;if(job.index==0)CleanupPath(job,new CleanupPoint(4.68f,-5.2f),new CleanupPoint(4.05f,-4.05f),new CleanupPoint(4.05f,targetZ),new CleanupPoint(targetX,targetZ));else CleanupPath(job,new CleanupPoint(4.05f,job.z),new CleanupPoint(4.05f,targetZ),new CleanupPoint(targetX,targetZ));}
  void TickCleanup(double dt){EnsureCleanupState();if(!State.introComplete)return;int selected=State.selected;var outlet=State.outlets[selected];if(outlet.nextLitterSeconds<=0)outlet.nextLitterSeconds=State.seconds+Balance.litterIntervalSeconds;if(State.seconds>=outlet.nextLitterSeconds){outlet.nextLitterSeconds=State.seconds+Balance.litterIntervalSeconds;if(outlet.dirt.Count(m=>m.kind!=0)<Balance.maxFloorLitter){int n=State.cleanupSequence;float[] corridors={-4f,-1.7f,.3f,2.3f};outlet.dirt.Add(new CleanupMess{id=++State.cleanupSequence,kind=1+n%2,x=(n%3-1)*.35f,z=corridors[(n/2)%4]-.45f,created=State.seconds});}}
   var job=State.cleanupJob;if(!job.active){if(State.queuedCleanup>=0&&CleanupWait<=0){int queued=State.queuedCleanup;State.queuedCleanup=-1;if(MessCount(queued)>0)StartCleanup(queued);}return;}
   if(job.phase==1){job.clock+=dt;job.yaw=0;if(job.clock>=Balance.cleanupSeconds){State.outlets[job.outlet].dirt.RemoveAll(m=>m.id==job.target);job.index++;SetCleanupTarget(job);}return;}
   if(job.waypoint<job.path.Count){var p=job.path[job.waypoint];float dx=p.x-job.x,dz=p.z-job.z,d=(float)Math.Sqrt(dx*dx+dz*dz),step=(float)(Balance.janitorSpeed*dt);if(d<=step){job.x=p.x;job.z=p.z;job.waypoint++;}else{job.x+=dx/d*step;job.z+=dz/d*step;}if(d>.0001)job.yaw=(float)(Math.Atan2(-dx,-dz)*180/Math.PI);}
   if(job.waypoint>=job.path.Count){if(job.phase==0){job.phase=1;job.clock=0;job.yaw=0;}else if(job.phase==2&&!job.paid){job.paid=true;job.active=false;State.cleanupReadyUtc=Now()+Balance.cleanupRewardIntervalSeconds;State.cleanupVisits++;State.cash+=job.reward;State.totalEarned+=job.reward;CleanupPaid?.Invoke(job.outlet,job.reward);}}
  }
 }
}
